{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const directory = dirname(fileURLToPath(import.meta.url));
const database = new DatabaseSync(process.env.DB_PATH || join(directory, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
    default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    due_date TEXT,
    notes TEXT NOT NULL DEFAULT '',
    deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))
  )
`);

// Keep a position for every task in every project it has belonged to. A task's
// current project remains on tasks; this table also remembers prior positions.
database.exec(`
  CREATE TABLE IF NOT EXISTS task_project_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id),
    UNIQUE (project_id, position)
  );
  INSERT INTO task_project_positions (task_id, project_id, position)
  SELECT id, project_id,
    ROW_NUMBER() OVER (PARTITION BY project_id ORDER BY id) - 1
  FROM tasks
  WHERE NOT EXISTS (SELECT 1 FROM task_project_positions);
`);

// Add persistent priorities to databases created by earlier versions of Workboard.
const taskColumns = database.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}

// Add the archive flag to databases created by earlier versions of Workboard.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!projectColumns.some((column) => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}

const listProjects = database.prepare(`
  SELECT p.id, p.name, p.archived,
    COUNT(CASE WHEN t.deleted = 0 THEN t.id END) AS total_count,
    COALESCE(SUM(CASE WHEN t.deleted = 0 THEN t.completed ELSE 0 END), 0) AS completed_count
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
`);
const findProject = database.prepare('SELECT id, name, archived, default_task_priority FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const setProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateProjectDefaultPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
// Add optional due dates to databases created before Task 009.
if (!taskColumns.some((column) => column.name === 'due_date')) {
  database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
}
if (!taskColumns.some((column) => column.name === 'notes')) {
  database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!taskColumns.some((column) => column.name === 'deleted')) {
  database.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))');
}

const setTaskDeleted = database.prepare('UPDATE tasks SET deleted = ? WHERE id = ? AND project_id = ?');
const listTasks = database.prepare(`SELECT t.id, t.title, t.completed, t.priority, t.due_date, t.notes, t.deleted
  FROM tasks t JOIN task_project_positions p ON p.task_id = t.id AND p.project_id = t.project_id
  WHERE t.project_id = ? ORDER BY p.position`);
const findTask = database.prepare('SELECT id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE id = ? AND project_id = ?');
const updateTaskNotes = database.prepare('UPDATE tasks SET notes = ? WHERE id = ? AND project_id = ?');
const updateTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
const updateTaskCompletion = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
function moveTask(taskId, sourceProjectId, destinationProjectId) {
  const task = findTask.get(taskId, sourceProjectId);
  if (!task) return null;
  database.exec('BEGIN');
  try {
    const rememberedPosition = database.prepare(`SELECT position FROM task_project_positions
      WHERE task_id = ? AND project_id = ?`).get(taskId, destinationProjectId);
    if (!rememberedPosition) {
      const nextPosition = database.prepare('SELECT COALESCE(MAX(position), -1) + 1 AS value FROM task_project_positions WHERE project_id = ?')
        .get(destinationProjectId).value;
      database.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)')
        .run(taskId, destinationProjectId, nextPosition);
    }
    database.prepare('UPDATE tasks SET project_id = ? WHERE id = ? AND project_id = ?')
      .run(destinationProjectId, taskId, sourceProjectId);
    const movedTask = findTask.get(taskId, destinationProjectId);
    database.exec('COMMIT');
    return movedTask;
  } catch (error) {
    database.exec('ROLLBACK');
    throw error;
  }
}

function isValidDueDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const [, year, month, day] = match.map(Number);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  const date = new Date(0);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCFullYear(year, month - 1, day);
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function sendJson(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(project = null) {
  const template = readFileSync(join(directory, 'index.html'), 'utf8');
  const initialProject = project ? JSON.stringify(project).replace(/</g, '\\u003c') : 'null';
  return template.replace('<!-- PROJECT_DATA -->', `<script>window.initialProject = ${initialProject};</script>`)
    .replace('<!-- PROJECT_HEADING -->', project ? escapeHtml(project.name) : '');
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 16_384) throw new Error('Request body too large');
  }
  return JSON.parse(body);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');

  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, listProjects.all(url.searchParams.get('filter') === 'Archived' ? 1 : 0));
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (request.method === 'POST' && archiveMatch) {
    const projectId = Number(archiveMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    setProjectArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, projectId);
    return sendJson(response, 200, findProject.get(projectId));
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (request.method === 'POST' && renameMatch) {
    const projectId = Number(renameMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 400, { error: 'Archived projects cannot be renamed' });
    try {
      const payload = await readJson(request);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      renameProject.run(name, projectId);
      return sendJson(response, 200, findProject.get(projectId));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const defaultPriorityMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/default-priority$/);
  if (request.method === 'PATCH' && defaultPriorityMatch) {
    const projectId = Number(defaultPriorityMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 400, { error: 'Archived projects cannot be changed' });
    try {
      const payload = await readJson(request);
      if (!['Low', 'Normal', 'High'].includes(payload.priority)) {
        return sendJson(response, 400, { error: 'A valid task priority is required' });
      }
      updateProjectDefaultPriority.run(payload.priority, projectId);
      return sendJson(response, 200, findProject.get(projectId));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const payload = await readJson(request);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return sendJson(response, 201, findProject.get(result.lastInsertRowid));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!findProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    if (request.method === 'GET') return sendJson(response, 200, listTasks.all(projectId));
    if (request.method === 'POST') {
      try {
        if (findProject.get(projectId).archived) return sendJson(response, 400, { error: 'Archived projects cannot have tasks' });
        const payload = await readJson(request);
        const title = typeof payload.title === 'string' ? payload.title.trim() : '';
        if (!title) return sendJson(response, 400, { error: 'Task title is required' });
        const project = findProject.get(projectId);
        const result = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)')
          .run(projectId, title, project.default_task_priority);
        const position = database.prepare('SELECT COALESCE(MAX(position), -1) + 1 AS value FROM task_project_positions WHERE project_id = ?')
          .get(projectId).value;
        database.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)')
          .run(result.lastInsertRowid, projectId, position);
        return sendJson(response, 201, findTask.get(result.lastInsertRowid, projectId));
      } catch {
        return sendJson(response, 400, { error: 'Invalid request' });
      }
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (request.method === 'PATCH' && taskMatch) {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    if (!findProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    try {
      if (findProject.get(projectId).archived) return sendJson(response, 400, { error: 'Archived project tasks cannot be changed' });
      const payload = await readJson(request);
      let result;
      if (typeof payload.completed === 'boolean') {
        result = updateTaskCompletion.run(payload.completed ? 1 : 0, taskId, projectId);
      } else if (['Low', 'Normal', 'High'].includes(payload.priority)) {
        result = updateTaskPriority.run(payload.priority, taskId, projectId);
      } else {
        return sendJson(response, 400, { error: 'A valid completion or priority is required' });
      }
      if (!Number(result.changes)) return sendJson(response, 404, { error: 'Task not found' });
      return sendJson(response, 200, findTask.get(taskId, projectId));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #202b3c; background: #f4f6f9; }
    body { margin: 0; }
    main { max-width: 760px; margin: 64px auto; padding: 0 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .detail, .task-row { background: white; border: 1px solid #dce2ea; border-radius: 10px; padding: 20px; }
    form { display: flex; align-items: end; gap: 12px; flex-wrap: wrap; }
    label { display: grid; gap: 7px; flex: 1; min-width: 200px; font-weight: 600; }
    input { box-sizing: border-box; width: 100%; padding: 10px 12px; border: 1px solid #aab5c4; border-radius: 6px; font: inherit; }
    textarea { box-sizing: border-box; width: 100%; min-height: 5em; padding: 10px 12px; border: 1px solid #aab5c4; border-radius: 6px; font: inherit; }
    button { padding: 10px 15px; border: 0; border-radius: 6px; background: #245fce; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #194da9; }
    .project-list { display: grid; gap: 10px; margin-top: 22px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .project-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .project-summary { color: #657083; white-space: nowrap; }
    .project-name { overflow-wrap: anywhere; }
    .alert { margin: 12px 0 0; color: #a32828; }
    .detail p { margin: 0 0 20px; }
    .task-controls { margin-top: 20px; }
    .task-controls label { flex: 1; }
    .task-row { display: flex; align-items: center; gap: 12px; }
    .task-row form { display: flex; align-items: end; gap: 8px; padding: 0; border: 0; flex: 1; }
    .task-row form label { min-width: 100px; }
    .task-row input { width: auto; }
    .task-row select { padding: 8px; border: 1px solid #aab5c4; border-radius: 6px; font: inherit; }
    .task-title { overflow-wrap: anywhere; }
    .task-row.completed .task-title { color: #657083; text-decoration: line-through; }
  </style>
</head>
<body>
  <main id="app">
    <h1>Workboard</h1>
    <form id="create-form">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Create project</button>
    </form>
    <p id="alert" class="alert" role="alert" hidden></p>
    <label for="project-filter" style="margin-top: 20px">Project filter</label>
    <select id="project-filter"><option>Active</option><option>Archived</option></select>
    <form id="project-search-form" class="task-controls">
      <label for="project-search">Project search</label>
      <input id="project-search" type="text" autocomplete="off">
      <button type="submit">Search projects</button>
    </form>
    <section id="project-list" class="project-list" aria-label="Projects"></section>
  </main>
  <main id="project-detail" hidden>
    <button id="back-button" type="button">Projects</button>
    <h1 id="project-heading"><!-- PROJECT_HEADING --></h1>
    <p id="archived-notice" hidden>Archived project</p>
    <form id="rename-form" class="task-controls">
      <label for="new-project-name">New project name</label>
      <input id="new-project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Rename project</button>
    </form>
    <p id="rename-alert" class="alert" role="alert" hidden></p>
    <label for="default-task-priority" style="margin-top: 20px">Default task priority</label>
    <select id="default-task-priority">
      <option>Low</option><option selected>Normal</option><option>High</option>
    </select>
    <form id="task-form" class="task-controls">
      <label for="task-title-input">Task title</label>
      <input id="task-title-input" name="title" type="text" autocomplete="off">
      <button type="submit">Create task</button>
    </form>
    <p id="task-alert" class="alert" role="alert" hidden></p>
    <label for="task-filter" style="margin-top: 20px">Task filter</label>
    <select id="task-filter">
      <option>All</option><option>Open</option><option>Completed</option><option>Deleted</option>
    </select>
    <form id="task-search-form" class="task-controls">
      <label for="task-search">Task search</label>
      <input id="task-search" type="text" autocomplete="off">
      <button type="submit">Search tasks</button>
    </form>
    <label for="priority-filter" style="margin-top: 20px">Priority filter</label>
    <select id="priority-filter">
      <option>All</option><option>Low</option><option>Normal</option><option>High</option>
    </select>
    <form id="due-range-form" class="task-controls">
      <label for="due-from">Due from<input id="due-from" type="text" placeholder="YYYY-MM-DD"></label>
      <label for="due-through">Due through<input id="due-through" type="text" placeholder="YYYY-MM-DD"></label>
      <button type="submit">Apply due range</button>
    </form>
    <p id="range-alert" class="alert" role="alert" hidden></p>
    <section id="task-list" class="project-list" aria-label="Tasks"></section>
  </main>
  <!-- PROJECT_DATA -->
  <script>
    const app = document.querySelector('#app');
    const detail = document.querySelector('#project-detail');
    if (window.initialProject) {
      app.hidden = true;
      detail.hidden = false;
      const projectId = window.initialProject.id;
      const list = document.querySelector('#task-list');
      const alert = document.querySelector('#task-alert');
      const input = document.querySelector('#task-title-input');
      const filter = document.querySelector('#task-filter');
      const priorityFilter = document.querySelector('#priority-filter');
      const rangeForm = document.querySelector('#due-range-form');
      const fromInput = document.querySelector('#due-from');
      const throughInput = document.querySelector('#due-through');
      const rangeAlert = document.querySelector('#range-alert');
      const taskSearchForm = document.querySelector('#task-search-form');
      const taskSearchInput = document.querySelector('#task-search');
      let appliedTaskQuery = '';
      const normalizeSearchText = (value) => value
        .replace(/[ \t]+/g, ' ')
        .replace(/[A-Z]/g, (letter) => letter.toLowerCase());
      let appliedRange = { from: '', through: '' };
      const archived = Boolean(window.initialProject.archived);
      let activeProjects = [];
      const defaultPriority = document.querySelector('#default-task-priority');
      defaultPriority.value = window.initialProject.default_task_priority || 'Normal';
      defaultPriority.disabled = archived;
      document.querySelector('#archived-notice').hidden = !archived;
      const renameInput = document.querySelector('#new-project-name');
      const renameButton = document.querySelector('#rename-form button');
      const renameAlert = document.querySelector('#rename-alert');
      renameInput.disabled = archived;
      renameButton.disabled = archived;
      document.querySelector('#task-title-input').disabled = archived;
      document.querySelector('#task-form button').disabled = archived;
      let tasks = [];
      const escapeText = (value) => {
        const element = document.createElement('span');
        element.textContent = value;
        return element.innerHTML;
      };
      const renderTasks = () => {
        const visibleTasks = tasks.filter((task) => {
          const matchesCompletion = (filter.value === 'Deleted' && task.deleted)
            || (filter.value !== 'Deleted' && !task.deleted && (filter.value === 'All'
              || (filter.value === 'Open' && !task.completed)
              || (filter.value === 'Completed' && task.completed)));
          const matchesPriority = priorityFilter.value === 'All' || task.priority === priorityFilter.value;
          const hasRange = appliedRange.from || appliedRange.through;
          const matchesDate = !hasRange || (task.due_date
            && (!appliedRange.from || task.due_date >= appliedRange.from)
            && (!appliedRange.through || task.due_date <= appliedRange.through));
          const matchesSearch = !appliedTaskQuery
            || normalizeSearchText(task.title).includes(normalizeSearchText(appliedTaskQuery));
          return matchesCompletion && matchesPriority && matchesDate && matchesSearch;
        });
        list.innerHTML = visibleTasks.map((task) => {
          const destinations = activeProjects.filter((project) => project.id !== projectId);
          const locked = archived || Boolean(task.deleted);
          const taskAction = task.deleted ? 'restore' : 'delete';
          const taskActionLabel = task.deleted ? 'Restore task' : 'Delete task';
          return `
          <div class="task-row${task.completed ? ' completed' : ''}" data-testid="task-row">
            <input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${escapeText(task.title)}"${task.completed ? ' checked' : ''}${locked ? ' disabled' : ''}>
            <span class="task-title">${escapeText(task.title)}</span>
            <form data-rename-task="${task.id}">
              <label>New task title<input type="text" name="title" value="${escapeText(task.title)}"${locked ? ' disabled' : ''}></label>
              <button type="submit"${locked ? ' disabled' : ''}>Rename task</button>
            </form>
            <label>Task priority<select data-task-priority="${task.id}"${locked ? ' disabled' : ''}>
              <option${task.priority === 'Low' ? ' selected' : ''}>Low</option>
              <option${task.priority === 'Normal' ? ' selected' : ''}>Normal</option>
              <option${task.priority === 'High' ? ' selected' : ''}>High</option>
            </select></label>
            <form data-due-date="${task.id}">
              <label>Task due date<input type="text" name="due_date" value="${escapeText(task.due_date || '')}" placeholder="YYYY-MM-DD"${locked ? ' disabled' : ''}></label>
              <button type="submit"${locked ? ' disabled' : ''}>Save due date</button>
            </form>
            <form data-task-notes="${task.id}">
              <label>Task notes<textarea name="notes"${locked ? ' disabled' : ''}>${escapeText(task.notes || '')}</textarea></label>
              <button type="submit"${locked ? ' disabled' : ''}>Save notes</button>
            </form>
            <label>Destination project<select data-destination="${task.id}"${locked || destinations.length === 0 ? ' disabled' : ''}>
              ${destinations.map((project) => `<option value="${project.id}">${escapeText(project.name)}</option>`).join('')}
            </select></label>
            <button type="button" data-move-task="${task.id}"${locked || destinations.length === 0 ? ' disabled' : ''}>Move task</button>
            <button type="button" data-task-lifecycle="${task.id}" data-action="${taskAction}"${archived ? ' disabled' : ''}>${taskActionLabel}</button>
          </div>`;
        }).join('');
      };
      const loadTasks = async () => {
        const response = await fetch(`/api/projects/${projectId}/tasks`);
        if (response.ok) {
          tasks = await response.json();
          renderTasks();
        }
      };
      fetch('/api/projects?filter=Active').then((response) => response.json()).then((projects) => {
        activeProjects = projects;
        renderTasks();
      });
      loadTasks();
      defaultPriority.addEventListener('change', async () => {
        const response = await fetch(`/api/projects/${projectId}/default-priority`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: defaultPriority.value }),
        });
        if (!response.ok) defaultPriority.value = window.initialProject.default_task_priority || 'Normal';
        else window.initialProject.default_task_priority = defaultPriority.value;
      });
      filter.addEventListener('change', renderTasks);
      priorityFilter.addEventListener('change', renderTasks);
      taskSearchForm.addEventListener('submit', (event) => {
        event.preventDefault();
        appliedTaskQuery = taskSearchInput.value.trim();
        renderTasks();
      });
      const validCalendarDate = (value) => {
        const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
        if (!match) return false;
        const [, y, m, d] = match.map(Number);
