        const visibleTasks = tasks.filter((task) => {
          const matchesCompletion = (filter.value === 'Deleted' && task.deleted)
            || (filter.value !== 'Deleted' && !task.deleted && (filter.value === 'All'
              || (filter.value === 'Open' && !task.completed)
              || (filter.value === 'Completed' && task.completed)));
          const matchesPriority = priorityFilter.value === 'All' || task.priority === priorityFilter.value;
          const hasRange = appliedRange.from || appliedRange.through;
          const matchesDate = !hasRange || (task.due_date
            && (!appliedRange.from || task.due_date >= appliedRange.from)
            && (!appliedRange.through || task.due_date <= appliedRange.through));
          const matchesSearch = !appliedTaskQuery
            || normalizeSearchText(task.title).includes(normalizeSearchText(appliedTaskQuery));
          return matchesCompletion && matchesPriority && matchesDate && matchesSearch;
        });
        list.innerHTML = visibleTasks.map((task) => {
          const destinations = activeProjects.filter((project) => project.id !== projectId);
          const locked = archived || Boolean(task.deleted);
          const taskAction = task.deleted ? 'restore' : 'delete';
          const taskActionLabel = task.deleted ? 'Restore task' : 'Delete task';
          return `
          <div class="task-row${task.completed ? ' completed' : ''}" data-testid="task-row">
            <input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${escapeText(task.title)}"${task.completed ? ' checked' : ''}${locked ? ' disabled' : ''}>
            <span class="task-title">${escapeText(task.title)}</span>
            <form data-rename-task="${task.id}">
              <label>New task title<input type="text" name="title" value="${escapeText(task.title)}"${locked ? ' disabled' : ''}></label>
              <button type="submit"${locked ? ' disabled' : ''}>Rename task</button>
            </form>
            <label>Task priority<select data-task-priority="${task.id}"${locked ? ' disabled' : ''}>
              <option${task.priority === 'Low' ? ' selected' : ''}>Low</option>
              <option${task.priority === 'Normal' ? ' selected' : ''}>Normal</option>
              <option${task.priority === 'High' ? ' selected' : ''}>High</option>
            </select></label>
            <form data-due-date="${task.id}">
              <label>Task due date<input type="text" name="due_date" value="${escapeText(task.due_date || '')}" placeholder="YYYY-MM-DD"${locked ? ' disabled' : ''}></label>
              <button type="submit"${locked ? ' disabled' : ''}>Save due date</button>
            </form>
            <form data-task-notes="${task.id}">
              <label>Task notes<textarea name="notes"${locked ? ' disabled' : ''}>${escapeText(task.notes || '')}</textarea></label>
              <button type="submit"${locked ? ' disabled' : ''}>Save notes</button>
            </form>
            <label>Destination project<select data-destination="${task.id}"${locked || destinations.length === 0 ? ' disabled' : ''}>
              ${destinations.map((project) => `<option value="${project.id}">${escapeText(project.name)}</option>`).join('')}
            </select></label>
            <button type="button" data-move-task="${task.id}"${locked || destinations.length === 0 ? ' disabled' : ''}>Move task</button>
            <button type="button" data-task-lifecycle="${task.id}" data-action="${taskAction}"${archived ? ' disabled' : ''}>${taskActionLabel}</button>
          </div>`;
        }).join('');
      };
      const loadTasks = async () => {
        const response = await fetch(`/api/projects/${projectId}/tasks`);
        if (response.ok) {
          tasks = await response.json();
          renderTasks();
        }
      };
      fetch('/api/projects?filter=Active').then((response) => response.json()).then((projects) => {
        activeProjects = projects;
        renderTasks();
      });
      loadTasks();
      defaultPriority.addEventListener('change', async () => {
        const response = await fetch(`/api/projects/${projectId}/default-priority`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: defaultPriority.value }),
        });
        if (!response.ok) defaultPriority.value = window.initialProject.default_task_priority || 'Normal';
        else window.initialProject.default_task_priority = defaultPriority.value;
      });
      filter.addEventListener('change', renderTasks);
      priorityFilter.addEventListener('change', renderTasks);
      taskSearchForm.addEventListener('submit', (event) => {
        event.preventDefault();
        appliedTaskQuery = taskSearchInput.value.trim();
        renderTasks();
      });
      const validCalendarDate = (value) => {
        const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
        if (!match) return false;
        const [, y, m, d] = match.map(Number);
        if (y < 1 || m < 1 || m > 12 || d < 1) return false;
        const date = new Date(0);
        date.setUTCHours(0, 0, 0, 0);
        date.setUTCFullYear(y, m - 1, d);
        return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
      };
      rangeForm.addEventListener('submit', (event) => {
        event.preventDefault();
        const from = fromInput.value.trim();
        const through = throughInput.value.trim();
        if ((from && !validCalendarDate(from)) || (through && !validCalendarDate(through))) {
          rangeAlert.textContent = 'Due range must use valid YYYY-MM-DD dates';
          rangeAlert.hidden = false;
          return;
        }
        if (from && through && from > through) {
          rangeAlert.textContent = 'Due from must not be after Due through';
          rangeAlert.hidden = false;
          return;
        }
        appliedRange = { from, through };
        rangeAlert.hidden = true;
        renderTasks();
      });
      list.addEventListener('submit', async (event) => {
        const notesForm = event.target.closest('form[data-task-notes]');
        if (notesForm) {
          event.preventDefault();
          const response = await fetch(`/api/projects/${projectId}/tasks/${notesForm.dataset.taskNotes}/notes`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ notes: notesForm.elements.notes.value }),
          });
          if (!response.ok) {
            const result = await response.json();
            alert.textContent = result.error || 'Unable to save notes';
            alert.hidden = false;
            return;
          }
          const updated = await response.json();
          tasks = tasks.map((task) => task.id === updated.id ? updated : task);
          alert.hidden = true;
          renderTasks();
          return;
        }
        const dueDateForm = event.target.closest('form[data-due-date]');
        if (dueDateForm) {
          event.preventDefault();
          const dueDateInput = dueDateForm.elements.due_date;
          const response = await fetch(`/api/projects/${projectId}/tasks/${dueDateForm.dataset.dueDate}/due-date`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ due_date: dueDateInput.value }),
          });
          if (!response.ok) {
            const result = await response.json();
            alert.textContent = result.error || 'Unable to save due date';
            alert.hidden = false;
            return;
          }
          const updated = await response.json();
          tasks = tasks.map((task) => task.id === updated.id ? updated : task);
          dueDateInput.value = updated.due_date || '';
          alert.hidden = true;
          renderTasks();
          return;
        }
        const form = event.target.closest('form[data-rename-task]');
        if (!form) return;
        event.preventDefault();
        const titleInput = form.elements.title;
        const title = titleInput.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          titleInput.focus();
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/tasks/${form.dataset.renameTask}/rename`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        if (!response.ok) {
          const result = await response.json();
          alert.textContent = result.error || 'Unable to rename task';
          alert.hidden = false;
          return;
        }
        const updated = await response.json();
        tasks = tasks.map((task) => task.id === updated.id ? updated : task);
        alert.hidden = true;
        renderTasks();
      });
      document.querySelector('#rename-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          renameAlert.textContent = 'Project name is required';
          renameAlert.hidden = false;
          renameInput.focus();
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/rename`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!response.ok) {
          const result = await response.json();
          renameAlert.textContent = result.error || 'Unable to rename project';
          renameAlert.hidden = false;
          return;
        }
        const project = await response.json();
        document.querySelector('#project-heading').textContent = project.name;
        renameInput.value = '';
        renameAlert.hidden = true;
      });
      document.querySelector('#task-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/tasks`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        if (!response.ok) {
          const result = await response.json();
          alert.textContent = result.error || 'Unable to create task';
          alert.hidden = false;
          return;
        }
        input.value = '';
        alert.hidden = true;
        await loadTasks();
      });
      list.addEventListener('change', async (event) => {
        const checkbox = event.target.closest('input[type="checkbox"][data-task-id]');
        const prioritySelect = event.target.closest('select[data-task-priority]');
        if (!checkbox && !prioritySelect) return;
        const taskId = checkbox ? checkbox.dataset.taskId : prioritySelect.dataset.taskPriority;
        const payload = checkbox ? { completed: checkbox.checked } : { priority: prioritySelect.value };
        const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
        if (response.ok) {
          const updated = await response.json();
          tasks = tasks.map((task) => task.id === updated.id ? updated : task);
          renderTasks();
        } else {
          await loadTasks();
        }
      });
      list.addEventListener('click', async (event) => {
        const lifecycleButton = event.target.closest('button[data-task-lifecycle]');
        if (lifecycleButton) {
          const taskId = lifecycleButton.dataset.taskLifecycle;
          const action = lifecycleButton.dataset.action;
          const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}/${action}`, { method: 'POST' });
          if (response.ok) {
            const updated = await response.json();
            tasks = tasks.map((task) => task.id === updated.id ? updated : task);
            renderTasks();
          } else {
            const result = await response.json();
            alert.textContent = result.error || `Unable to ${action} task`;
            alert.hidden = false;
          }
          return;
        }
        const button = event.target.closest('button[data-move-task]');
        if (!button) return;
        const taskId = button.dataset.moveTask;
        const destination = list.querySelector(`select[data-destination="${taskId}"]`);
        if (!destination || !destination.value) return;
        const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}/move`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ destination_project_id: Number(destination.value) }),
        });
        if (response.ok) {
          tasks = tasks.filter((task) => task.id !== Number(taskId));
          renderTasks();
        } else {
          const result = await response.json();
          alert.textContent = result.error || 'Unable to move task';
          alert.hidden = false;
        }
      });
    } else {
      const list = document.querySelector('#project-list');
      const alert = document.querySelector('#alert');
      const input = document.querySelector('#project-name');
      const filter = document.querySelector('#project-filter');
      const searchForm = document.querySelector('#project-search-form');
      const searchInput = document.querySelector('#project-search');
      let appliedQuery = '';
      const normalizeSearchText = (value) => value
        .replace(/[ \t]+/g, ' ')
        .replace(/[A-Z]/g, (letter) => letter.toLowerCase());
      const escapeText = (value) => {
        const element = document.createElement('span');
        element.textContent = value;
        return element.innerHTML;
      };
      const render = (projects) => {
        const visibleProjects = projects.filter((project) => !appliedQuery
          || normalizeSearchText(project.name).includes(normalizeSearchText(appliedQuery)));
        list.innerHTML = visibleProjects.map((project) => `
          <div class="project-row" data-testid="project-row">
            <span class="project-name">${escapeText(project.name)}</span>
            <span class="project-summary" data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
            <span class="project-actions">
              <button type="button" data-project-id="${project.id}" data-action="open">Open project</button>
              <button type="button" data-project-id="${project.id}" data-action="${project.archived ? 'restore' : 'archive'}">${project.archived ? 'Restore project' : 'Archive project'}</button>
            </span>
          </div>`).join('');
      };
      const loadProjects = () => fetch(`/api/projects?filter=${filter.value}`).then((response) => response.json()).then(render);
      loadProjects();
      filter.addEventListener('change', loadProjects);
      searchForm.addEventListener('submit', (event) => {
        event.preventDefault();
        appliedQuery = searchInput.value.trim();
        loadProjects();
      });
      document.querySelector('#create-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!response.ok) {
          const result = await response.json();
          alert.textContent = result.error || 'Unable to create project';
          alert.hidden = false;
          return;
        }
        const project = await response.json();
        input.value = '';
        alert.hidden = true;
        await loadProjects();
      });
      list.addEventListener('click', async (event) => {
        const button = event.target.closest('button[data-project-id]');
        if (!button) return;
        const { projectId, action } = button.dataset;
        if (action === 'open') {
          window.location.href = `/projects/${projectId}`;
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/${action}`, { method: 'POST' });
        if (response.ok) await loadProjects();
      });
    }
    document.querySelector('#back-button').addEventListener('click', () => {
      window.location.href = '/';
    });
  </script>
</body>
</html>

